using CompanyManagement.Api.DTOs; using CompanyManagement.Api.Services; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc;
namespace CompanyManagement.Api.Controllers;
[ApiController,Route("api/clientes"),Authorize] public class ClientesController(IClienteService service):ControllerBase { [HttpGet] public async Task<ActionResult> Get()=>Ok(await service.All()); [HttpGet("{id:int}")] public async Task<ActionResult> Get(int id)=>(await service.Get(id)) is { } c?Ok(c):NotFound(); [HttpPost] public async Task<ActionResult> Post(ClienteCreateDto d){var r=await service.Create(d);return r.data is { } c?CreatedAtAction(nameof(Get),new{id=c.Id},c):Conflict(new ProblemDetails{Title=r.error,Status=409});} [HttpPut("{id:int}")] public async Task<ActionResult> Put(int id,ClienteUpdateDto d){var r=await service.Update(id,d);return r.ok?NoContent():r.error=="Cliente no encontrado."?NotFound():Conflict(new ProblemDetails{Title=r.error,Status=409});} [HttpDelete("{id:int}"),Authorize(Roles="Admin")] public async Task<ActionResult> Delete(int id){var r=await service.Delete(id);return r.ok?NoContent():r.error=="Cliente no encontrado."?NotFound():Conflict(new ProblemDetails{Title=r.error,Status=409});} }
